from pathlib import Path
import re
root=Path(__file__).resolve().parents[1]/'dist'
home=(root/'index.html').read_text()
header=home[home.index('  <div id="top">'):home.index('  <main id="main">')].replace('<h1 class="masthead-title">','<div class="masthead-title">').replace('</h1>','</div>')
footer=home[home.index('  <footer class="site-footer">'):home.index('    <script src=')]
def links(s):return re.sub(r'href="#([^"]*)"',lambda m:'href="index.html#'+m[1]+'"',s)
body='''<main class="sada-page" id="main"><header class="sada-opening sada-shell"><p class="eyebrow">Syria Civic · Syria Direct</p><h1>Sada House</h1><div class="sada-opening-row"><p>An intellectual hub in Damascus.</p><a href="https://sadahouse.com">Visit Sada House ↗</a></div></header>
<div class="sada-shell sada-source-photos"><img src="https://sadahouse.com/assets/bulletin-2.jpg" alt="A speaker in conversation at Sada House."><img src="https://sadahouse.com/assets/bulletin-4.jpg" alt="Two audience members listening at Sada House." loading="lazy"></div>
<section class="sada-introduction sada-shell" aria-label="About Sada House"><div><p>We bring people together around book talks, panels, film screenings, and even the occasional trivia night.</p><p>Sada House is a shared home in Mazra’a District, Damascus, founded by Syria Direct and Syria Civic.</p></div><div><p>Here, people across professions and generations can meet, exchange ideas, and find collaborators.</p><p>Our lending library offers books, newspapers, and reference materials to anyone in the city.</p></div></section>
<section class="sada-collective" id="collective" aria-labelledby="collective-title"><div class="sada-shell"><p class="eyebrow">A shared home</p><h2 id="collective-title">Sada<br>Collective<span aria-hidden="true">✳</span></h2><p class="collective-deck">A shared home for the organizations shaping Damascus's cultural and civic life.</p><p class="collective-intro">Sada House opens its doors to independent organizations, cultural initiatives, student groups, and community projects. Through Sada Collective, we provide space, resources, and a wider audience to help these groups bring their ideas to life.</p><div class="collective-photo"><img src="assets/sada-listeners.jpg" alt="People listening and exchanging ideas at Sada House" loading="lazy"><p>A place for your next idea.</p></div><h3>What partners receive</h3><div class="collective-benefits"><article><h4>A regular home.</h4><p>Free access to Sada House for workshops, discussions, and public events.</p></article><article><h4>A wider audience.</h4><p>Promotion through Sada House's website, social media, and mailing list.</p></article><article><h4>Shared resources.</h4><p>Access to event equipment, the lending library, and other facilities.</p></article><article><h4>A community of collaborators.</h4><p>Opportunities to connect with other partner organizations, develop joint initiatives, and share ideas.</p></article></div><a href="mailto:info@syriadirect.org?subject=Sada%20Collective">Ask about joining Sada Collective →</a></div></section>
<section class="sada-invitation sada-shell"><div><h2>Have an idea for Sada House?</h2><p>To host a private event or inquire about the space, write to <a href="mailto:info@syriadirect.org">info@syriadirect.org</a></p></div><div class="sada-invitation-links"><a href="https://sadahouse.com">Visit sadahouse.com ↗</a></div></section></main>'''
font=re.search(r'https://fonts.googleapis.com/css2\?[^\"]+',home).group()
head=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Sada House — Syria Civic</title><meta name="description" content="A cultural space in central Damascus, run by Syria Civic with Syria Direct. Book talks, public discussions, film screenings, and a lending library."><link href="{font}" rel="stylesheet"><link rel="stylesheet" href="styles.css"><link rel="stylesheet" href="sada.css?v=editorial20"><link rel="icon" type="image/png" href="assets/favicon.png"></head><body><a class="skip-link" href="#main">Skip to content</a>'''
(root/'sada-house.html').write_text(head+links(header)+body+links(footer)+'<script src="script.js"></script></body></html>')
